<?php
 class crm_passworddb_notices extends common_notices { const NOTICE_TEMPLATES = [ 'crm-passworddb-new-request' => [ 'tasks' => 'crm', 'persist' => true, 'title' => 'Новая заявка', 'confirmText' => 'Аккредитовать', 'cancelText' => 'Отмена', 'modal' => true, 'widget' => 'crm-passworddb-approvalsedit', 'tpl' => [ '<div>Необходимо обработать заявку на пароль к БД.</div>', '<table class="fieldset">', '<tr><td>Клиент: </td><td>{clientName}</td></tr>', '<tr><td>БД: </td><td>{dbName}</td></tr>', '<tpl if="authorNote">', '<tr><td>Примечание: </td><td>{authorNote}</td></tr>', '<tpl else>', '<tr><td>Примечание: </td><td>не указана</td></tr>', '</tpl>', '</table>' ] ], 'crm-passworddb-new-approval' => [ 'tasks' => 'crm', 'persist' => true, 'title' => 'Ответ на заявку', 'confirmText' => 'Открыть', 'cancelText' => 'Закрыть', 'modal' => true, 'widget' => 'crm-passworddb-passwordget', 'tpl' => [ '<div>Ответ: ', '<span class="attention">', '<tpl if="status===2">', 'положительный', '<tpl else>', 'отрицательный', '</tpl>', '</span>.', '</div>', '<table class="fieldset">', '<tr><td>Клиент: </td><td>{clientName}</td></tr>', '<tr><td>БД: </td><td>{dbName}</td></tr>', '<tpl if="authorNote">', '<tr><td>Примечание: </td><td>{authorNote}</td></tr>', '<tpl else>', '<tr><td>Примечание: </td><td>не указана</td></tr>', '</tpl>', '</table>' ] ], ]; protected static function filterNoticeTypes(array &$types): void { parent::filterNoticeTypes($types); $db = connectDb(); $userId = getSessionValue('user'); $sql = <<<SQL
SELECT rbac_test_access('password_db_request', 0, $userId) "request", rbac_test_access('password_db_approve', 0, $userId) "approve"
SQL;
$access = selectSql($db, $sql)[0]; if (!$access['request']) { unset($types['crm-passworddb-new-request']); } if (!$access['approve']) { unset($types['crm-passworddb-new-approval']); } } }